corrected_code:
const { MongoClient, ObjectId } = require('mongodb');
const { buildSubgraphSchema } = require('@apollo/subgraph');
const { GraphQLError } = require('graphql');
const gql = require('graphql-tag');

const mongoClient = new MongoClient(process.env.MONGODB_URI);

const typeDefs = gql`
  extend schema @link(url: "https://specs.apollo.dev/federation/v2.0", import: ["@key", "@external"])

  extend type SupportTicket @key(fields: "id") {
    id: ID! @external
    internalNotes: [String!]!
  }
`;

const resolvers = {
  SupportTicket: {
    internalNotes: async (parent, args, context) => {
      if (!context.user || !context.user.isSupportAgent) {
        throw new GraphQLError('Access denied to internal staff notes', { extensions: { code: 'FORBIDDEN' } });
      }
      const db = mongoClient.db('helpdesk');
      const ticket = await db.collection('tickets').findOne(
        { _id: new ObjectId(parent.id) },
        { projection: { staffNotes: 1 } }
      );
      return ticket?.staffNotes || [];
    }
  }
};
